TWAIDriver canB(static_cast<gpio_num_t>(CAN_TX),
                static_cast<gpio_num_t>(CAN_RX));
static MCP2515Driver canA(MCP2515_CS, MCP2515_RST, MCP2515_SCLK, MCP2515_MISO,
                          MCP2515_MOSI, &SPI, 10000000);
uint32_t replayIndex = 0;
uint32_t lastReplayUs = 0;
bool replayDone = false;

void printFrame(const char *prefix, const CanFrame &frame) {
  Serial.printf("%s id=0x%03lX dlc=%u data=", prefix,
                static_cast<unsigned long>(frame.id), frame.dlc);
  for (uint8_t i = 0; i < frame.dlc && i < 8; ++i) {
    if (frame.data[i] < 16)
      Serial.print('0');
    Serial.print(frame.data[i], HEX);
    if (i + 1 < frame.dlc)
      Serial.print(' ');
  }
  Serial.println();
}

void sendNextReplayFrame() {
  if (replayDone)
    return;

  if (lastReplayUs == 0) {
    lastReplayUs = micros();
    return;
  }

  int framesSentThisLoop = 0;
  // Cap at 10 frames per loop to prevent death-spiral blocking RX
  while (!replayDone && micros() - lastReplayUs >= 500 &&
         framesSentThisLoop < 10) {
    if (replayIndex >= REPLAY_FRAME_COUNT) {
      replayIndex = 0;
      Serial.println("Replay looping from start...");
    }

    ReplayFrame replay;
    memcpy_P(&replay, &REPLAY_FRAMES[replayIndex], sizeof(replay));

    CanFrame frame;
    frame.id = replay.id;
    frame.dlc = replay.dlc <= 8 ? replay.dlc : 8;
    memcpy(frame.data, replay.data, sizeof(frame.data));
    canB.send(frame);
    replayIndex++;

    lastReplayUs += 500;
    framesSentThisLoop++;
  }

  // If we fell too far behind (e.g. CAN bus saturated), reset the timer so we
  // don't queue an infinite backlog
  if (micros() - lastReplayUs > 5000) {
    lastReplayUs = micros();
  }
}

void readCanB() {
  CanFrame frame;
  while (canB.read(frame))
    printFrame("RX CAN_B", frame);
}

void readCanA() {
  CanFrame frame;
  while (canA.read(frame))
    printFrame("RX CAN_A", frame);
}

void setup() {
  Serial.begin(921600);
  delay(1000);
  setCanTxEnabled(true);
  if (!canB.init()) {
    Serial.println("CAN_B init failed");
    return;
  }
  canB.setBusMode(CanBusMode::Normal);
  canB.setFilters(nullptr, 0);

  SPI.begin(MCP2515_SCLK, MCP2515_MISO, MCP2515_MOSI, MCP2515_CS);
  if (!canA.init()) {
    Serial.println("CAN_A init failed");
  } else {
    canA.setBusMode(CanBusMode::Normal);
    canA.setFilters(nullptr, 0);
  }
  Serial.printf("CAN_B replay ready: %lu frames\n",
                static_cast<unsigned long>(REPLAY_FRAME_COUNT));
}

void loop() {
  sendNextReplayFrame();
  readCanA();
  readCanB();
}
